#include <iostream>
#include <vector>
#include <string>
using namespace std;

long long count(vector<int>& cells, int n, vector<int>& rows, vector<int>& cols, int full) {
    int best = -1, bestMask = 0, bestCount = n + 1;
    for (int i = 0; i < n * n; i++) {
        if (cells[i] != 0) continue;
        int mask = ~(rows[i / n] | cols[i % n]) & full;
        int c = __builtin_popcount(mask);
        if (c < bestCount) {
            best = i;
            bestMask = mask;
            bestCount = c;
            if (c <= 1) break;
        }
    }
    if (best == -1) return 1;
    if (bestCount == 0) return 0;
    int r = best / n, c0 = best % n;
    long long total = 0;
    for (int d = 1; d <= n; d++) {
        int bit = 1 << d;
        if (!(bestMask & bit)) continue;
        cells[best] = d;
        rows[r] |= bit;
        cols[c0] |= bit;
        total += count(cells, n, rows, cols, full);
        cells[best] = 0;
        rows[r] &= ~bit;
        cols[c0] &= ~bit;
    }
    return total;
}

int main() {
    long long n;
    cin >> n;
    vector<string> grid(n);
    for (int i = 0; i < n; i++) {
        cin >> grid[i];
    }

    vector<int> cells(n * n), rowsM(n, 0), colsM(n, 0);
    bool clash = false;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int d = grid[i][j] - '0';
            cells[i * n + j] = d;
            if (d) {
                int bit = 1 << d;
                if ((rowsM[i] & bit) || (colsM[j] & bit)) clash = true;
                rowsM[i] |= bit;
                colsM[j] |= bit;
            }
        }
    }
    int full = (1 << (n + 1)) - 2;
    cout << (clash ? 0 : count(cells, (int)n, rowsM, colsM, full)) << "\n";

    return 0;
}

